<template>
  <div class="app-container">
    <div class="workspace-heading"><div><h2>{{ finance?'学校财务 · 退款管理':'我的退款申请' }}</h2><p>全额模拟退款 · 审核通过后，需登记完成凭证才会扣减项目净筹款。</p></div><el-button @click="load">刷新</el-button></div>
    <el-card shadow="never">
      <el-form inline><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:200px"><el-option v-for="s in states" :key="s" :value="s" :label="label(s)" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="query.current=1;load()">查询</el-button></el-form-item></el-form>
      <el-table :data="list" stripe v-loading="loading"><el-table-column prop="refundNo" label="退款单号" min-width="240" show-overflow-tooltip /><el-table-column prop="projectTitle" label="项目" min-width="160" /><el-table-column label="金额" width="120"><template #default="{row}">￥{{ amount(row.amount) }}</template></el-table-column><el-table-column label="状态" min-width="160"><template #default="{row}"><el-tag>{{ label(row.status) }}</el-tag></template></el-table-column><el-table-column label="退款存证" min-width="180"><template #default="{row}">{{ evidence(row.evidenceStatus) }}</template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" @click="open(row,'detail')">详情</el-button><el-button v-if="canManage&&row.status==='PENDING'" link type="primary" @click="open(row,'audit')">审核</el-button><el-button v-if="canManage&&row.status==='WAIT_REFUND'" link type="primary" @click="open(row,'complete')">登记完成</el-button></template></el-table-column></el-table>
      <div class="table-pagination"><el-pagination :total="total" layout="total,prev,pager,next" v-model:current-page="query.current" :page-size="query.size" @current-change="load" /></div>
    </el-card>
    <el-dialog v-model="visible" :title="mode==='audit'?'审核退款申请':mode==='complete'?'登记模拟退款完成':'退款详情'" width="min(640px,94vw)" :close-on-click-modal="!busy && !uploading" :close-on-press-escape="!busy && !uploading" :show-close="!busy && !uploading">
      <el-descriptions border :column="1"><el-descriptions-item label="公益项目">{{ current.projectTitle }}</el-descriptions-item><el-descriptions-item label="退款单号">{{ current.refundNo }}</el-descriptions-item><el-descriptions-item label="原捐赠 ID">{{ current.donationId }}</el-descriptions-item><el-descriptions-item label="全额退款">￥{{ amount(current.amount) }}</el-descriptions-item><el-descriptions-item label="申请原因">{{ current.reason }}</el-descriptions-item><el-descriptions-item label="状态">{{ label(current.status) }}</el-descriptions-item><el-descriptions-item label="审核意见">{{ current.opinion || '-' }}</el-descriptions-item><el-descriptions-item label="审核人员 ID">{{ current.auditUserId || '—' }}</el-descriptions-item><el-descriptions-item label="审核时间">{{ time(current.auditTime) }}</el-descriptions-item><el-descriptions-item label="完成登记人员 ID">{{ current.completeUserId || '—' }}</el-descriptions-item><el-descriptions-item label="完成时间">{{ time(current.completeTime) }}</el-descriptions-item><el-descriptions-item label="存证状态">{{ evidence(current.evidenceStatus) }}</el-descriptions-item><el-descriptions-item v-if="current.evidenceTxId" label="退款存证交易 ID">{{ current.evidenceTxId }}</el-descriptions-item></el-descriptions>
      <el-alert :title="nextStep" type="info" :closable="false" style="margin-top:16px" /><el-button v-if="!finance && current.status==='REJECTED'" type="primary" style="margin-top:12px" @click="$router.push('/donor/donations')">返回我的捐赠记录重新申请</el-button>
      <p v-if="current.voucherFileId"><el-button link type="primary" @click="download(current.voucherFileId)">下载完成凭证</el-button></p>
      <el-form :disabled="busy" v-if="mode==='audit'" label-width="100px" style="margin-top:20px"><el-form-item label="审核结果"><el-radio-group v-model="form.result"><el-radio value="PASS">通过</el-radio><el-radio value="REJECT">驳回</el-radio></el-radio-group></el-form-item><el-form-item label="审核意见"><el-input v-model="form.opinion" type="textarea" maxlength="1000" /></el-form-item></el-form>
      <el-form :disabled="busy" v-if="mode==='complete'" label-width="100px" style="margin-top:20px"><el-form-item label="完成凭证"><el-upload action="#" :auto-upload="false" :limit="1" :on-change="upload" v-model:file-list="fileList" :disabled="busy || uploading" :on-remove="()=>form.voucherFileId=null"><el-button :loading="uploading">上传完成凭证</el-button></el-upload></el-form-item><el-form-item label="完成时间"><el-date-picker v-model="form.completeTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item></el-form>
      <template #footer><el-button :disabled="busy || uploading" @click="visible=false">关闭</el-button><el-button v-if="mode!=='detail'" type="primary" :loading="busy" :disabled="uploading" @click="submit">提交</el-button></template>
    </el-dialog>
  </div>
</template>
<script>
import { listRefunds,refundDetail,auditRefund,completeRefund,statusLabel,evidenceLabel } from '@/api/finance'
import { uploadFile,downloadFile } from '@/api/file'
import { formatAmount,formatTime } from '@/utils/format'
import moment from 'moment'
import refreshWorkspace from '@/utils/refreshWorkspace'
export default {name:'RefundWorkspace',mixins:[refreshWorkspace],data:()=>({list:[],total:0,loading:false,busy:false,uploading:false,visible:false,current:{},form:{},fileList:[],mode:'detail',states:['PENDING','WAIT_REFUND','REJECTED','REFUNDED'],query:{current:1,size:10,status:''}}),computed:{finance(){return ['ADMIN','AUDITOR'].includes(this.$store.getters.role)},canManage(){return this.$store.getters.role==='ADMIN'},nextStep(){return {PENDING:'退款申请已保存，等待学校审核。审核通过前不扣减筹款。',REJECTED:'查看审核意见后，可回到我的捐赠记录重新申请全额测试退款。',WAIT_REFUND:'学校已同意退款，等待登记完成凭证和完成时间；此时筹款尚未扣减。',REFUNDED:'全额测试退款已完成，项目净筹款已扣减一次。存证任务独立处理，请以上方存证状态为准。'}[this.current.status]||''}},created(){this.load()},methods:{label:statusLabel,evidence:evidenceLabel,amount:formatAmount,time:formatTime,
  async load(){this.loading=true;try{const r=await listRefunds(this.query,this.finance);this.list=r.data.records;this.total=r.data.total}finally{this.loading=false}},
  async open(row,mode){const r=await refundDetail(row.refundId);this.current=r.data;this.mode=mode;this.form={result:'PASS',opinion:'',voucherFileId:null,completeTime:moment().format('YYYY-MM-DDTHH:mm:ss')};this.fileList=[];this.visible=true},
  async upload(file){this.uploading=true;try{const r=await uploadFile(file.raw,'REFUND_VOUCHER',this.current.refundId);this.form.voucherFileId=r.data.fileId;this.$message.success('完成凭证已保存到服务器')}catch(e){this.fileList=[];this.form.voucherFileId=null}finally{this.uploading=false}},
  async download(id){try{await downloadFile(id)}catch(e){this.$message.error(e.message)}},
  async submit(){if(this.busy)return;if(this.mode==='audit'&&this.form.result==='REJECT'&&!this.form.opinion.trim())return this.$message.warning('驳回必须填写意见');if(this.mode==='complete'&&(!this.form.voucherFileId||!this.form.completeTime))return this.$message.warning('请上传凭证并填写完成时间');this.busy=true;try{if(this.mode==='audit')await auditRefund(this.current.refundId,{result:this.form.result,opinion:this.form.opinion});else await completeRefund(this.current.refundId,{voucherFileId:this.form.voucherFileId,completeTime:this.form.completeTime});this.$message.success(this.mode==='complete'?'退款完成已登记，净筹款已更新，存证后台处理中':this.form.result==='PASS'?'退款已审核通过，请继续登记退款完成凭证':'退款已驳回，学生可查看意见后重新申请');this.visible=false;await this.load()}finally{this.busy=false}}
}}
</script>
